using NexusAndroid;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;

namespace NexusAndroid.Tests.Engine;

// Contracts run in declaration order, once per test run (ContractSuite); each one is a test case.
internal static class EngineContracts
{
    public static void Run(Action<string, Action> Test)
    {
void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
bool Throws(Action run,string contains){try{run();return false;}catch(Exception e)when(NativeSafety.Recoverable(e)){/* assertion helper: observes whatever the engine throws */return e.Message.Contains(contains,StringComparison.OrdinalIgnoreCase);}}
string Text(JsonObject r)=>string.Join('\n',r["content"]!.AsArray().OfType<JsonObject>().Select(c=>c["text"]?.ToString()??""));
JsonObject Obj(string json)=>JsonNode.Parse(json)!.AsObject();
var fixture=new FakePhone();var adb=new FakeAdb(fixture);var dir=Path.Join(TestPaths.Transfers,"fixture-"+Guid.NewGuid().ToString("N"));var engine=new NativeEngine(adb,fixture,dir,()=>new FakeControl(fixture));
Test("All 18 reference schemas expose actual arguments and typed outputs",()=>{var tools=NativeSchemas.Tools().OfType<JsonObject>().ToList();Assert(tools.Count==18,"tool count");var act=tools.Single(t=>t["name"]!.ToString()=="act");Assert(act["inputSchema"]?["$defs"]?["Step"]?["properties"]?["do"] is not null,"do missing");foreach(var name in new[]{"phone","settings","info"}){Assert(tools.Single(t=>t["name"]?.ToString()==name)["outputSchema"] is JsonObject,"typed output missing");}Assert(tools.Any(t=>t["name"]?.ToString()=="map"),"map alias drift");});
Test("phone is concise structured status and never dumps battery",()=>{var r=engine.Execute("phone",new());Assert(r["structuredContent"]?["foreground"]?.ToString()=="com.example.app","foreground");Assert(Text(r).Length<500&&!adb.Commands.Any(c=>c.Contains("battery")),"battery dump");});
Test("checkup reconnects a remembered phone before reporting it disconnected",()=>{var phone=new FakePhone();var link=new FakeAdb(phone){HideUntilPicked=true};var status=new NativeEngine(link,phone,Path.Join(dir,"checkup-first"),()=>new FakeControl(phone)).Execute("checkup",new());Assert(status["structuredContent"]?["connected"]?.GetValue<bool>()==true&&link.Picked,"checkup returned before connection selection");});
Test("settings read has no writes",()=>{adb.Commands.Clear();var r=engine.Execute("settings",Obj("{\"name\":\"wifi\"}"));Assert(Text(r)=="wifi: on","wifi value");Assert(!adb.Commands.Any(c=>c.Contains("put")||c.Contains("svc")),"read mutated setting");});
Test("wireless ADB cannot disable Wi-Fi",()=>{adb.Commands.Clear();Assert(Throws(()=>engine.Execute("settings",Obj("{\"name\":\"wifi\",\"value\":\"off\"}")),"refused"),"not refused");Assert(!adb.Commands.Any(c=>c.Contains("svc")),"mutating command sent");});
Test("look emits numbered references and masks codes",()=>{fixture.Label="Code de validation 482913";var r=engine.Execute("look",new());Assert(Text(r).Contains("[1]")&&!Text(r).Contains("482913"),"unmasked or missing ref");fixture.Label="Open";});
Test("documented do and target dispatch to observed coordinates",()=>{adb.Commands.Clear();fixture.ChangeOnInput=true;engine.Execute("look",new());var result=engine.Execute("act",Obj("{\"steps\":[{\"do\":\"tap\",\"target\":\"[1]\"}]}"));Assert(adb.Inputs.Count==1&&adb.Inputs[0].Contains("'150' '240'"),"wrong or missing tap");Assert(result["structuredContent"]?["verified"]?.GetValue<bool>()==true,"effect not verified");fixture.Changed=false;fixture.ChangeOnInput=false;});
Test("unknown old action schema is refused before any input",()=>{adb.Commands.Clear();Assert(Throws(()=>engine.Execute("act",Obj("{\"steps\":[{\"action\":\"tap\",\"target\":\"Open\"}]}")),"do"),"not refused");Assert(adb.Inputs.Count==0,"input sent");});
Test("blind target is never converted to 0,0",()=>{adb.Commands.Clear();var r=engine.Execute("act",Obj("{\"steps\":[{\"do\":\"tap\"}]}"));Assert(Text(r).Contains("Missing target")&&adb.Inputs.Count==0,"blind tap");});
Test("outward gesture needs exact one-use agreement and replay sends nothing",()=>
{
    adb.Commands.Clear();fixture.Label="Send";engine.Execute("look",new());var denied=engine.Execute("act",Obj("{\"steps\":[{\"do\":\"tap\",\"target\":\"Send\"}]}"));Assert(adb.Inputs.Count==0&&Text(denied).Contains("Exact action requiring"),"unconfirmed send");
    var request=Obj("{\"steps\":[{\"do\":\"tap\",\"target\":\"Send\",\"confirm\":true}]}");var proposal=engine.Execute("act",request);var token=Regex.Match(Text(proposal),@"accord=([a-f0-9]{48})").Groups[1].Value;Assert(token.Length==48&&adb.Inputs.Count==0,"missing proposal");request["steps"]![0]!["accord"]=token;engine.Execute("act",request);Assert(adb.Inputs.Count==1,"agreed send missing");engine.Execute("act",request);Assert(adb.Inputs.Count==1,"token replay sent input");fixture.Label="Open";
});
Test("changed screen invalidates token",()=>{adb.Commands.Clear();fixture.Label="Send";var request=Obj("{\"steps\":[{\"do\":\"tap\",\"target\":\"Send\",\"confirm\":true}]}");var p=engine.Execute("act",request);var token=Regex.Match(Text(p),@"accord=([a-f0-9]{48})").Groups[1].Value;fixture.Context="different recipient";request["steps"]![0]!["accord"]=token;engine.Execute("act",request);Assert(adb.Inputs.Count==0,"changed action accepted");fixture.Label="Open";fixture.Context="recipient A";});
