Test("unconfirmed uninstall and core removal both send nothing",()=>{adb.Commands.Clear();Assert(Throws(()=>engine.Execute("apps",Obj("{\"action\":\"uninstall\",\"app\":\"com.example.app\"}")),"Confirmation"),"uninstall allowed");Assert(Throws(()=>engine.Execute("apps",Obj("{\"action\":\"clear\",\"app\":\"com.android.settings\",\"confirm\":true}")),"Core"),"core clear allowed");Assert(!adb.Commands.Any(c=>c.Contains("'uninstall'")||c.Contains("'clear'")),"destruction sent");});
Test("functions uses real catalog instead of placeholder",()=>{var r=engine.Execute("functions",new());Assert(Text(r).Contains("findNotes")&&!Text(r).Contains("engine ready"),"placeholder");});
Test("unknown AppFunction cannot run without explicit confirmation",()=>{adb.Commands.Clear();Assert(Throws(()=>engine.Execute("functions",Obj("{\"action\":\"run\",\"app\":\"com.example.app\",\"function\":\"unknownVerb\"}")),"Confirmation"),"unknown function executed");Assert(!adb.Commands.Any(c=>c.Contains("execute-app-function")),"function executed");});
Test("known read AppFunction runs and preserves params",()=>{adb.Commands.Clear();var r=engine.Execute("functions",Obj("{\"action\":\"run\",\"app\":\"com.example.app\",\"function\":\"findNotes\",\"params\":{\"findNotesParams\":{}}}"));Assert(adb.Commands.Any(c=>c.Contains("execute-app-function")&&c.Contains("findNotesParams")),"function not executed");Assert(Text(r).Contains("answer"),"response lost");});
Test("web query is read-only, never opens Chrome or Maps",()=>{adb.Commands.Clear();engine.Execute("web",Obj("{\"query\":\"something\"}"));Assert(!adb.Commands.Any(c=>c.Contains("'am'")||c.Contains("'start'")),"web navigated");});
Test("file traversal and sensitive PC paths are refused",()=>{Assert(Throws(()=>NativeSafety.PhonePath("/sdcard/../../data/data"),"shared"),"phone traversal");Assert(Throws(()=>NativeSafety.PcPath(Path.Join(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"OneDrive","Documents","NexusSecure","agents","token"),true),"Sensitive"),"secret path");});
Test("MCP initialize negotiates protocol and failures are errors",()=>{var server=new McpServer(engine);var init=server.HandleRequest(Obj("{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{\"protocolVersion\":\"2025-06-18\"}}"));Assert(init?["result"]?["protocolVersion"]?.ToString()=="2025-06-18","wrong protocol");var error=server.HandleRequest(Obj("{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/call\",\"params\":{\"name\":\"does_not_exist\"}}"));Assert(error?["result"]?["isError"]?.GetValue<bool>()==true,"error disguised");});
