Test("act reports toasts shown during the gestures, codes masked, protected apps left out",()=>{fixture.ChangeOnInput=true;fixture.ToastRows.Add(new(){["seq"]="1",["package"]="com.example.app",["text"]="Earlier toast",["age_ms"]="9000"});fixture.ToastsOnInput.AddRange([("com.android.systemui","Copié"),("com.example.app","Code de validation 482913"),("com.example.bank","Solde 1 234 €")]);engine.Execute("look",new());var r=engine.Execute("act",Obj("{\"steps\":[{\"do\":\"tap\",\"target\":\"[1]\"}]}"));var toasts=r["structuredContent"]?["toasts"]?.AsArray();Assert(Text(r).Contains("Toast com.android.systemui: Copié")&&toasts?.Count==2&&!Text(r).Contains("482913")&&!Text(r).Contains("Solde")&&!Text(r).Contains("Earlier"),"toasts missing, unmasked, protected or stale");fixture.ChangeOnInput=false;fixture.Changed=false;fixture.ToastRows.Clear();fixture.ToastsOnInput.Clear();});
