Test("protected apps refuse local irreversible and anonymous buttons despite confirmation",()=>{fixture.TargetPackage="com.revolut.revolut";foreach(var label in new[]{"Supprimer définitivement",""}){fixture.Label=label;adb.Commands.Clear();var result=engine.Execute("act",Obj("{\"steps\":[{\"do\":\"tap\",\"target\":\"id:button\",\"confirm\":true,\"accord\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"}]}"));Assert(adb.Inputs.Count==0&&Text(result).Contains("refused"),"protected irreversible or anonymous input accepted");}fixture.Label="Open";fixture.TargetPackage="";});
Test("real process ArgumentList preserves file quotes spaces Unicode and selected device",()=>{var executable=Environment.ProcessPath??throw new Exception("fixture executable unknown");var link=new AdbClient(executable){SelectedSerial="fixture-device"};var arguments=new[]{"--argv-fixture","pull","-a","/sdcard/quo\"ted/été 猫.txt",Path.Join(dir,"destination with spaces","été 猫.txt")};var result=JsonNode.Parse(link.RunAdbArgs(arguments).Stdout)!.AsArray().Select(node=>node!.ToString()).ToArray();Assert(result.SequenceEqual(new[]{"-s","fixture-device"}.Concat(arguments)),"process argv was split or reinterpreted");});
Test("outward agreement binds recipient context outside the foreground package",()=>{fixture.Label="Send";fixture.TargetPackage="com.example.messenger";fixture.ContextPackage="com.example.messenger";fixture.Context="recipient A";adb.Commands.Clear();var request=Obj("{\"steps\":[{\"do\":\"tap\",\"target\":\"id:button\",\"confirm\":true}]}");var proposal=engine.Execute("act",request);var token=Regex.Match(Text(proposal),@"accord=([a-f0-9]{48})").Groups[1].Value;Assert(token.Length==48,"proposal absent");fixture.Context="recipient B";request["steps"]![0]!["accord"]=token;engine.Execute("act",request);Assert(adb.Inputs.Count==0,"old agreement applied to changed split-screen recipient");fixture.Label="Open";fixture.TargetPackage="";fixture.ContextPackage="";fixture.Context="recipient A";});
Test("warm phone status uses one fresh identity-bound ADB batch and no UI/helper read",()=>{var phone=new FakePhone();var link=new FakeAdb(phone);link.PickDevice();var query=new CountingQuery(phone);var statusEngine=new NativeEngine(link,query,Path.Join(dir,"batch-status"),()=>new FakeControl(phone));link.Commands.Clear();statusEngine.Execute("phone",new());Assert(query.Screens==0&&link.Commands.Count==1&&link.Commands[0].Contains("@@NEXUS-STATUS@@")&&link.Commands[0].Contains("ro.serialno")&&link.Commands[0].Contains("boot_id"),"phone fetched UI or repeated identity/status processes");});
Test("operation identity is released before shutdown can restore another phone",()=>{var phone=new FakePhone();var link=new FakeAdb(phone);var root=Path.Join(dir,"scope-identity");var runtime=new NativeEngine(link,phone,root,()=>new FakeControl(phone));runtime.Execute("phone",new());File.WriteAllText(Path.Join(root,"awake.json"),new JsonObject{["active"]=true,["phone"]="fixture-hardware",["serial"]="127.0.0.1:12345",["original"]=30000,["last"]=0,["pid"]=Environment.ProcessId}.ToJsonString());link.Hardware="other-physical-phone";link.Commands.Clear();runtime.Shutdown();Assert(link.Commands.Any(command=>command.Contains("ro.serialno"))&&!link.Commands.Any(command=>command.Contains("'settings' 'put'")),"operation proof leaked into unrelated shutdown restoration");});
Test("phone recovers a lost Wi-Fi transport once to the same phone over USB",()=>{var phone=new FakePhone();var link=new FakeAdb(phone){DeviceSerial="fixture-usb",SelectedSerial="192.0.2.44:5555",LoseFirstStatus=true};var runtime=new NativeEngine(link,phone,Path.Join(dir,"phone-reconnect"),()=>new FakeControl(phone));var result=runtime.Execute("phone",new());Assert(link.StatusReads==2&&link.Picked&&result["structuredContent"]?["serial"]?.ToString()=="fixture-usb"&&result["structuredContent"]?["transport"]?.ToString()=="usb"&&link.Inputs.Count==0,"status reconnection absent, repeated, foreign or injected input");});
Test("phone does not retry or adopt a mismatching hardware status sample",()=>{var phone=new FakePhone();var link=new FakeAdb(phone){SelectedSerial="192.0.2.44:5555",Hardware="foreign-hardware"};var runtime=new NativeEngine(link,phone,Path.Join(dir,"phone-foreign"),()=>new FakeControl(phone));Assert(Throws(()=>runtime.Execute("phone",new()),"identity changed")&&link.StatusReads==1&&!link.Picked&&link.Inputs.Count==0,"foreign status triggered reconnect/adoption");});
    }
}


